import React, { useState } from 'react';
import { Shield, Download } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Hayvan Sigortası & TARSİM Hasar Tazminat Dosyası
 * Devlet Destekli Tarım Sigortaları (TARSİM) hasar ihbarı ve eksper tazminat dosyası üreticisi.
 */

export default function TarsimInsuranceModal({ isOpen, onClose, animal = {} }) {
  const [policyNo, setPolicyNo] = useState('TRSM-2026-94812');
  const [claimType, setClaimType] = useState('Ölüm / İtlaf');
  const [lossReason, setLossReason] = useState('Doğum Komplikasyonu / Uterus Yırtılması');
  const [estimatedValue, setEstimatedValue] = useState('85000');
  const [veterinarian, setVeterinarian] = useState('Vet. Hekim Serdar K.');

  if (!isOpen) return null;

  const handleDownloadClaim = () => {
    const claimDoc = `=====================================================
T.C. DEVLET DESTEKLİ TARIM SİGORTALARI HAVUZU (TARSİM)
BÜYÜKBAŞ / KÜÇÜKBAŞ HAYVAN HAYAT SİGORTASI HASAR İHBAR FORMU
=====================================================

POLİÇE BİLGİLERİ:
• Poliçe No: ${policyNo}
• Sigortalı İşletme: mFk Farm Hayvancılık İşletmesi
• İhbar Tarihi: ${new Date().toLocaleDateString('tr-TR')}

HAYVAN KİMLİK BİLGİLERİ:
• Küpe No: ${animal.code || 'TR16-00482'}
• Hayvan Adı: ${animal.name || 'Sarıkız'}
• Türü / Irkı: ${animal.species || 'Sığır'} / ${animal.breed || 'Holstein'}
• Cinsiyeti: ${animal.gender === 'F' ? 'Dişi' : 'Erkek'}
• Mevcut Canlı Ağırlık: ${animal.current_weight || 580} kg

HASAR / TAZMİNAT DETAYLARI:
• Hasar Türü: ${claimType}
• Tespit Edilen Neden: ${lossReason}
• Sigorta Bedeli / Talep Edilen Tazminat: ₺${parseFloat(estimatedValue).toLocaleString('tr-TR')}
• Otopsi / Teşhis Yapan Veteriner Hekim: ${veterinarian}

EKLER:
[x] Kulak küpesi ile çekilmiş hayvan fotoğrafları
[x] Veteriner Hekim Otopsi ve İmha Raporu
[x] TÜRKVET Sisteminden Düşüm / Ölüm Belgesi

Eksper Atama Çağrı Merkezi: 0850 250 82 77
Form oluşturulma zamanı: ${new Date().toISOString()}
=====================================================`;

    const blob = new Blob([claimDoc], { type: 'text/plain;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `TARSIM_Hasar_Dosyasi_${animal.code || 'Hayvan'}.txt`;
    a.click();
    toast.success('TARSİM hasar tazminat dosyası hazırlandı ve indirildi!');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 bg-black/60 backdrop-blur-xs">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="bg-blue-700 text-white p-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Shield className="w-5 h-5 text-blue-200" />
            <h3 className="font-bold text-sm">TARSİM Hasar Tazminat Dosyası</h3>
          </div>
          <button onClick={onClose} className="text-white/80 hover:text-white font-bold">✕</button>
        </div>

        <div className="p-4 space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-[11px] font-bold text-gray-600 mb-1">TARSİM Poliçe No</label>
              <input
                type="text"
                value={policyNo}
                onChange={(e) => setPolicyNo(e.target.value)}
                className="w-full text-xs font-mono border border-gray-200 rounded-lg p-2 bg-gray-50 font-bold"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-gray-600 mb-1">Hasar Türü</label>
              <select
                value={claimType}
                onChange={(e) => setClaimType(e.target.value)}
                className="w-full text-xs border border-gray-200 rounded-lg p-2 bg-gray-50"
              >
                <option>Ölüm / İtlaf</option>
                <option>Mecburi Kesim (Acil)</option>
                <option>Yavru Atma (Abortus)</option>
                <option>Sakatlık / Verim Kaybı</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-[11px] font-bold text-gray-600 mb-1">Hasar / Ölüm Nedeni</label>
            <input
              type="text"
              value={lossReason}
              onChange={(e) => setLossReason(e.target.value)}
              className="w-full text-xs border border-gray-200 rounded-lg p-2"
            />
          </div>

          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-[11px] font-bold text-gray-600 mb-1">Poliçe Teminat Bedeli (₺)</label>
              <input
                type="number"
                value={estimatedValue}
                onChange={(e) => setEstimatedValue(e.target.value)}
                className="w-full text-xs font-bold border border-gray-200 rounded-lg p-2 text-blue-700"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-gray-600 mb-1">Teşhis Yapan Veteriner</label>
              <input
                type="text"
                value={veterinarian}
                onChange={(e) => setVeterinarian(e.target.value)}
                className="w-full text-xs border border-gray-200 rounded-lg p-2"
              />
            </div>
          </div>

          <div className="flex items-center gap-2 pt-2 border-t">
            <button
              type="button"
              onClick={onClose}
              className="btn-secondary flex-1 text-xs py-2 px-3"
            >
              İptal
            </button>
            <button
              type="button"
              onClick={handleDownloadClaim}
              className="btn-primary flex-1 text-xs py-2 px-3 flex items-center justify-center gap-1.5 font-bold"
            >
              <Download className="w-3.5 h-3.5" /> Dosyayı İndir
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
