import React, { useState } from 'react';
import { GitBranch, ExternalLink, User, ChevronDown, ChevronRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

/**
 * 4 Nesil İnteraktif Soykütüğü Aile Ağacı
 * Hayvanın anne, baba, büyükanneanne, büyükbaba ve ötesini görsel ağaç yapısında sunar.
 * Soy bağlantılarını renk kodlu (dişi=pembe, erkek=mavi) kartlarla gösterir.
 */
export default function PedigreeTreeViewer({ animal, farmId }) {
  const navigate = useNavigate();
  const [expanded, setExpanded] = useState({ mother: true, father: true });

  if (!animal) return null;

  const toggle = (key) => setExpanded(prev => ({ ...prev, [key]: !prev[key] }));

  const AncestorCard = ({ ancestor, gender, label, generation = 1 }) => {
    const isFemale = gender === 'F';
    const colorClass = isFemale
      ? 'bg-pink-50 border-pink-200 text-pink-900'
      : 'bg-blue-50 border-blue-200 text-blue-900';
    const badgeClass = isFemale
      ? 'bg-pink-100 text-pink-700'
      : 'bg-blue-100 text-blue-700';
    const indent = `ml-${generation * 4}`;

    if (!ancestor) {
      return (
        <div className={`${indent} flex items-center gap-2 py-1.5 px-3 rounded-lg border border-dashed border-gray-200 text-gray-400 text-xs mb-1.5`}>
          <User className="w-3 h-3" /> {label}: Bilinmiyor
        </div>
      );
    }

    return (
      <div className={`${indent} flex items-center justify-between gap-2 py-2 px-3 rounded-xl border ${colorClass} text-xs mb-1.5 shadow-xs`}>
        <div className="flex items-center gap-2 min-w-0">
          <span className={`px-1.5 py-0.5 rounded-full text-[9px] font-black uppercase ${badgeClass} shrink-0`}>
            {label}
          </span>
          <span className="font-bold truncate">{ancestor.name}</span>
          <span className="font-mono text-[10px] opacity-70 truncate">{ancestor.code}</span>
          {ancestor.breed && (
            <span className="text-[10px] opacity-60 truncate hidden sm:inline">{ancestor.breed}</span>
          )}
        </div>
        <button
          onClick={() => navigate(`/animals/${ancestor.id}${farmId ? `?farm_id=${farmId}` : ''}`)}
          className="shrink-0 text-inherit opacity-60 hover:opacity-100 transition"
          title="Kart Detayı"
        >
          <ExternalLink className="w-3.5 h-3.5" />
        </button>
      </div>
    );
  };

  const mother = animal.mother;
  const father = animal.father;
  const grandMotherMat = mother?.mother;
  const grandFatherMat = mother?.father;
  const grandMotherPat = father?.mother;
  const grandFatherPat = father?.father;

  return (
    <div className="card shadow-sm border border-gray-100">
      <div className="flex items-center gap-2 mb-4 pb-2 border-b">
        <div className="p-2 bg-emerald-50 text-emerald-700 rounded-xl">
          <GitBranch className="w-4 h-4" />
        </div>
        <div>
          <h3 className="font-bold text-gray-900 text-sm">4 Nesil Soykütüğü Ağacı</h3>
          <p className="text-[11px] text-gray-400">Anne ve baba hatları boyunca büyükanne/büyükbabalar</p>
        </div>
      </div>

      {/* Merkez hayvan */}
      <div className="flex items-center gap-2.5 py-2.5 px-4 rounded-2xl bg-emerald-50 border border-emerald-200 mb-4">
        <div className="w-8 h-8 rounded-full bg-emerald-200 flex items-center justify-center font-black text-emerald-800 text-xs">
          {animal.name?.[0]?.toUpperCase() || '?'}
        </div>
        <div>
          <p className="font-black text-gray-900 text-sm">{animal.name}</p>
          <p className="text-[11px] font-mono text-gray-500">{animal.code} • {animal.species} {animal.breed ? `(${animal.breed})` : ''}</p>
        </div>
        <span className={`ml-auto px-2 py-0.5 rounded-full text-[10px] font-black uppercase ${animal.gender === 'F' ? 'bg-pink-100 text-pink-700' : 'bg-blue-100 text-blue-700'}`}>
          {animal.gender === 'F' ? '♀ Dişi' : '♂ Erkek'}
        </span>
      </div>

      {/* Anne Hattı */}
      <div className="mb-3">
        <button
          onClick={() => toggle('mother')}
          className="flex items-center gap-2 text-xs font-bold text-pink-700 mb-2 hover:text-pink-900 transition"
        >
          {expanded.mother ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
          ♀ Anne Hattı (Maternal Line)
        </button>
        {expanded.mother && (
          <div>
            <AncestorCard ancestor={mother} gender="F" label="Anne" generation={0} />
            {mother && (
              <>
                <AncestorCard ancestor={grandMotherMat} gender="F" label="Büyükanneanne" generation={1} />
                <AncestorCard ancestor={grandFatherMat} gender="M" label="Büyükbabaanne" generation={1} />
              </>
            )}
          </div>
        )}
      </div>

      {/* Baba Hattı */}
      <div>
        <button
          onClick={() => toggle('father')}
          className="flex items-center gap-2 text-xs font-bold text-blue-700 mb-2 hover:text-blue-900 transition"
        >
          {expanded.father ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
          ♂ Baba Hattı (Paternal Line)
        </button>
        {expanded.father && (
          <div>
            <AncestorCard ancestor={father} gender="M" label="Baba" generation={0} />
            {father && (
              <>
                <AncestorCard ancestor={grandMotherPat} gender="F" label="Büyükannebaba" generation={1} />
                <AncestorCard ancestor={grandFatherPat} gender="M" label="Büyükbabababa" generation={1} />
              </>
            )}
          </div>
        )}
      </div>

      {(!mother && !father) && (
        <div className="text-center py-6 text-gray-400 text-xs">
          Bu hayvan için soykütüğü bilgisi girilmemiş. Hayvanı düzenleyerek anne ve baba ekleyebilirsiniz.
        </div>
      )}
    </div>
  );
}
